(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.KanjiCpuPoints=api;})(typeof window!=='undefined'?window:globalThis,function(){'use strict';function gain(winner,difficulty='normal'){return winner===true?({normal:25,hard:45,boss:75}[difficulty]||25):winner===false?-({normal:15,hard:20,boss:25}[difficulty]||15):0;}function settle(state,winner,difficulty){const before=state.rating;state.rating=Math.max(0,Math.min(1000000000,before+gain(winner,difficulty)));return state.rating-before;}return{gain,settle};});
